        for dx,v in enumerate(row):
            if v is not None: g[top[0]+dy][top[1]+dx]=v
    for r,c in markers:g[r][c]=next(v for row in g for v in row if v!=bg) if False else marker_color
    return g

def expected_by_centers(g,bg,motif,top,markers,mark):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]
    # erase markers before writing the copies
    for r,c in markers:o[r][c]=bg
    hh,ww=len(motif),len(motif[0]); oy=(hh-1)//2; ox=(ww-1)//2
    for r,c in markers:
        for dy in range(hh):
            for dx in range(ww):
                v=motif[dy][dx]
                if v is not None and v!=bg:
                    y,x=r+dy-oy,c+dx-ox
                    if 0<=y<h and 0<=x<w:o[y][x]=v
    # source motif remains; markers do not overlap it for these demos
    return o

def make_demo(h,w,bg, motif, top, markers, mark):
    g=[[bg]*w for _ in range(h)]
    for dy,row in enumerate(motif):
        for dx,v in enumerate(row):
            if v is not None:g[top[0]+dy][top[1]+dx]=v
    for r,c in markers:g[r][c]=mark
    expected=expected_by_centers(g,bg,motif,top,markers,mark)
    return g,expected
